param(
    [string]$RepoPath = "."
)

$ErrorActionPreference = "Stop"

function Fail([string]$Message) {
    Write-Host ""
    Write-Host "ERROR: $Message" -ForegroundColor Red
    exit 1
}

try {
    $RepoPath = (Resolve-Path $RepoPath).Path
} catch {
    Fail "找不到仓库目录：$RepoPath"
}

if (-not (Test-Path (Join-Path $RepoPath ".git"))) {
    Fail "指定目录不是 Git 仓库：$RepoPath"
}

Write-Host "Kana Study v7 学习活跃度热力图补丁" -ForegroundColor Cyan
Write-Host "仓库：$RepoPath"
Write-Host ""

$files = @(
    @{ Path = 'index.html'; OldMarker = 'id="historyList"'; NewMarker = 'id="activityHeatmap"'; Base64 = '' }
    @{ Path = 'css/progress.css'; OldMarker = '.history-list'; NewMarker = '.activity-heatmap'; Base64 = '' }
    @{ Path = 'css/responsive.css'; OldMarker = '.history-item'; NewMarker = '.activity-mobile-tip'; Base64 = '' }
    @{ Path = 'js/ui.js'; OldMarker = 'function renderHistory() {'; NewMarker = 'function renderActivityHeatmap() {'; Base64 = '' }
    @{ Path = 'js/app.js'; OldMarker = '.register("./sw.js?v=6")'; NewMarker = '.register("./sw.js?v=7")'; Base64 = '' }
    @{ Path = 'sw.js'; OldMarker = 'const CACHE_NAME = "kana-study-v6";'; NewMarker = 'const CACHE_NAME = "kana-study-v7";'; Base64 = '' }
)

# 如果所有目标文件都已经是新版本，直接结束，避免重复覆盖。
$allAlreadyApplied = $true

foreach ($item in $files) {
    $target = Join-Path $RepoPath $item.Path

    if (-not (Test-Path $target)) {
        $allAlreadyApplied = $false
        break
    }

    $content = [IO.File]::ReadAllText($target)

    if (-not $content.Contains($item.NewMarker)) {
        $allAlreadyApplied = $false
        break
    }
}

if ($allAlreadyApplied) {
    Write-Host "补丁已经应用过，无需重复执行。" -ForegroundColor Green
    exit 0
}

Write-Host "1/5 检查当前版本..." -ForegroundColor Yellow

foreach ($item in $files) {
    $target = Join-Path $RepoPath $item.Path

    if (-not (Test-Path $target)) {
        Fail "缺少文件：$($item.Path)"
    }

    $content = [IO.File]::ReadAllText($target)

    if (-not $content.Contains($item.OldMarker)) {
        Fail "文件不是预期的 v6 版本，已停止修改：$($item.Path)`n缺少版本标记：$($item.OldMarker)"
    }

    Write-Host ("  OK  " + $item.Path)
}

$timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
$repoParent = Split-Path -Parent $RepoPath
$repoName = Split-Path -Leaf $RepoPath
$backupRoot = Join-Path $repoParent "$repoName-heatmap-backup-$timestamp"

Write-Host ""
Write-Host "2/5 备份即将修改的文件..." -ForegroundColor Yellow

foreach ($item in $files) {
    $source = Join-Path $RepoPath $item.Path
    $backup = Join-Path $backupRoot $item.Path
    $backupDir = Split-Path -Parent $backup

    if ($backupDir) {
        New-Item -ItemType Directory -Force -Path $backupDir | Out-Null
    }

    Copy-Item -LiteralPath $source -Destination $backup -Force
}

Write-Host "备份目录：$backupRoot"

Write-Host ""
Write-Host "3/5 应用热力图补丁..." -ForegroundColor Yellow

foreach ($item in $files) {
    $target = Join-Path $RepoPath $item.Path
    $bytes = [Convert]::FromBase64String($item.Base64)

    [IO.File]::WriteAllBytes($target, $bytes)

    $written = [IO.File]::ReadAllText($target)

    if (-not $written.Contains($item.NewMarker)) {
        Fail "写入后的文件校验失败：$($item.Path)"
    }

    Write-Host ("  OK  " + $item.Path)
}

Write-Host ""
Write-Host "4/5 执行语法和 Git 校验..." -ForegroundColor Yellow

$node = Get-Command node -ErrorAction SilentlyContinue

if ($node) {
    $jsChecks = @(
        "js/ui.js",
        "js/app.js",
        "sw.js"
    )

    foreach ($relativePath in $jsChecks) {
        $target = Join-Path $RepoPath $relativePath

        & node --check $target

        if ($LASTEXITCODE -ne 0) {
            Fail "JavaScript 语法检查失败：$relativePath"
        }
    }

    Write-Host "JavaScript 语法检查通过。" -ForegroundColor Green
} else {
    Write-Host "未检测到 Node.js，跳过 node --check。" -ForegroundColor DarkYellow
}

$git = Get-Command git -ErrorAction SilentlyContinue

if ($git) {
    & git -C $RepoPath diff --check

    if ($LASTEXITCODE -ne 0) {
        Fail "git diff --check 未通过"
    }

    Write-Host "git diff --check 通过。" -ForegroundColor Green
} else {
    Write-Host "未检测到 Git，跳过 Git 校验。" -ForegroundColor DarkYellow
}

Write-Host ""
Write-Host "5/5 修改完成。" -ForegroundColor Green
Write-Host ""
Write-Host "本次修改内容："
Write-Host "  - 用 GitHub 风格学习活跃度热力图替换“最近 7 天学习历史”"
Write-Host "  - 显示过去 365 天记录"
Write-Host "  - 颜色按当天练习题数分 0~4 级"
Write-Host "  - 点击日期可查看题数、正确、错误和正确率"
Write-Host "  - 显示今年学习天数与最长连续学习天数"
Write-Host "  - 手机端支持横向滑动，并自动定位到最近日期"
Write-Host "  - 静态资源版本号升级到 v7，PWA Cache 升级到 kana-study-v7"
Write-Host ""
Write-Host "原文件备份："
Write-Host "  $backupRoot"

if ($git) {
    Write-Host ""
    Write-Host "Git 变更："
    & git -C $RepoPath diff --stat -- `
        index.html `
        css/progress.css `
        css/responsive.css `
        js/ui.js `
        js/app.js `
        sw.js

    Write-Host ""
    & git -C $RepoPath status --short

    Write-Host ""
    Write-Host "确认网页正常后提交："
    Write-Host "  git add index.html css/progress.css css/responsive.css js/ui.js js/app.js sw.js"
    Write-Host '  git commit -m "feat: replace study history with activity heatmap"'
    Write-Host "  git push"
}
